const sessionManager = require("./session-manager").getInstance(null);

class KumvaIVREngine {
    constructor(RED) {
        this.RED = RED;
        this.waitingNodes = new Map(); // nodeId -> node instance (in-memory cache)

        // Listen for resume events from webhook
        RED.events.on('kumva:resume', this.handleResume.bind(this));
    }

    registerWaitingNode(node) {
        this.waitingNodes.set(node.id, node);
        console.log(`Registered waiting node: ${node.type} (${node.id})`);
    }

    async handleResume(data) {
        const { sessionId, response, nodeId } = data;
        const session = await sessionManager.getSession(sessionId);
        if (!session) return;

        const waitingNode = this.waitingNodes.get(nodeId);
        if (waitingNode && typeof waitingNode.onResponse === 'function') {
            const msg = {
                payload: response,
                dtmfDigits: response,
                sessionId: sessionId,
                phoneNumber: session.phoneNumber,
                _kumvaResume: true
            };
            waitingNode.onResponse(msg);
        } else {
            console.warn(`No waiting node found for ${nodeId}`);
        }
    }

    async storeResponse(sessionId, questionId, response) {
        // TODO: Connect to Save Response node later
        console.log(`Stored: ${questionId} = ${response} for session ${sessionId}`);
    }
}

let engineInstance;
module.exports = {
    getInstance: (RED) => {
        if (!engineInstance) engineInstance = new KumvaIVREngine(RED);
        return engineInstance;
    }
};